"""Example functionality that is identical under Python 2 and Python 3.

The functions here avoid version specific ``str``/``bytes`` behaviour by
always converting through :mod:`mylib.compat`.
"""

from __future__ import absolute_import, division, print_function, unicode_literals

import base64
import json

from .compat import iteritems, string_types, to_bytes, to_text

__all__ = ["greet", "encode", "decode", "loads", "iter_dict"]


def greet(name):
    """Return a friendly greeting for *name*.

    ``name`` may be a byte string or a text string on either interpreter;
    the result is always a text string.
    """
    if not isinstance(name, string_types):
        raise TypeError("name must be a string")
    return "Hello, {0}!".format(to_text(name))


def encode(data):
    """Base64 encode *data* and return the result as text.

    Accepting and returning text keeps the value identical on Python 2 and
    Python 3, where ``base64`` otherwise straddles ``str`` and ``bytes``.
    """
    return to_text(base64.b64encode(to_bytes(data)))


def decode(data):
    """Reverse :func:`encode`, returning the decoded value as text."""
    return to_text(base64.b64decode(to_bytes(data)))


def loads(data):
    """Deserialize a JSON document from bytes or text."""
    return json.loads(to_text(data))


def iter_dict(mapping):
    """Iterate over the ``(key, value)`` pairs of *mapping* efficiently.

    On Python 2 this avoids materialising a list as ``dict.items`` would.
    """
    return iteritems(mapping)

from __future__ import absolute_import, unicode_literals

import pytest

from mylib.compat import PY2, PY3, binary_type, text_type, to_bytes, to_text


def test_python_version_flags_are_consistent():
    assert PY2 != PY3


def test_to_bytes_from_text():
    result = to_bytes("héllo")
    assert isinstance(result, binary_type)
    assert result == "héllo".encode("utf-8")


def test_to_bytes_is_idempotent():
    value = b"already bytes"
    assert to_bytes(value) is value


def test_to_text_from_bytes():
    result = to_text(b"h\xc3\xa9llo")
    assert isinstance(result, text_type)
    assert result == "héllo"


def test_to_text_is_idempotent():
    value = "already text"
    assert to_text(value) is value


@pytest.mark.parametrize("value", [1, None, object()])
def test_to_bytes_rejects_non_strings(value):
    with pytest.raises(TypeError):
        to_bytes(value)


@pytest.mark.parametrize("value", [1, None, object()])
def test_to_text_rejects_non_strings(value):
    with pytest.raises(TypeError):
        to_text(value)

from __future__ import absolute_import, unicode_literals

import pytest

from mylib import decode, encode, greet, iter_dict, loads
from mylib.compat import text_type


def test_greet_with_text():
    assert greet("World") == "Hello, World!"


def test_greet_with_bytes():
    assert greet(b"World") == "Hello, World!"


def test_greet_returns_text():
    assert isinstance(greet("World"), text_type)


def test_greet_rejects_non_strings():
    with pytest.raises(TypeError):
        greet(42)


@pytest.mark.parametrize("value", ["", "hello", "héllo", "a" * 512])
def test_encode_decode_roundtrip(value):
    assert decode(encode(value)) == value


def test_encode_matches_base64_module():
    import base64

    assert encode("payload") == base64.b64encode(b"payload").decode("ascii")


def test_decode_accepts_bytes():
    assert decode(b"cGF5bG9hZA==") == "payload"


def test_loads_from_bytes_and_text():
    assert loads(b'{"a": 1}') == {"a": 1}
    assert loads('{"a": 1}') == {"a": 1}


def test_iter_dict_yields_pairs():
    assert sorted(iter_dict({"b": 2, "a": 1})) == [("a", 1), ("b", 2)]

